L4_1 = {}
L4_1.m_CutScenKey_Talk = "PRYDWEN_ACT2_INTERUDE5@4#Talk"
L4_1.m_CutScenProcessKey = 4
L4_1.m_CutScenID = 6000209
L4_1.m_CutScenStrID = "PRYDWEN_ACT2_INTERUDE5"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_Talk_KOREA = "성찬을 준비하라. 새로운 날이 당도하리니."
L4_1.m_fTalkTime = 0.03
L4_1.m_bTalkCenterFadeIn = true
L4_1.m_Talk_JPN = "聖餐を準備しろ。新しい日が到来する。"
L4_1.m_Talk_ENG = "Prepare the feast. A new dawn is coming."
L4_1.m_Talk_TWN = "預備盛宴吧。新天已來到。"
L4_1.m_Talk_SCN = "准备盛宴吧，新的一天即将到来。"
L4_1.m_Talk_DEU = "Prepare the feast. A new dawn is coming."
L4_1.m_Talk_FRA = "Prepare the feast. A new dawn is coming."
L5_1 = {}
L5_1.m_CutScenKey_Talk = "PRYDWEN_ACT2_INTERUDE5@5#Talk"
L5_1.m_CutScenProcessKey = 5
L5_1.m_CutScenID = 6000209
L5_1.m_CutScenStrID = "PRYDWEN_ACT2_INTERUDE5"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_Talk_KOREA = "불완전한 지식, 불완전한 존재들이 성찬을 통해 하나가 되어, 완전해질 것이다."
L5_1.m_fTalkTime = 0.03
L5_1.m_bTalkCenterFadeIn = true
L5_1.m_Talk_JPN = "不完全な知識、不完全な存在たちが聖餐により一つになり、完全体となる。"
L5_1.m_Talk_ENG = "The feast will complete the imperfect knowledge and perfect the imperfect beings."
L5_1.m_Talk_TWN = "不完整的知識，不完整的存在將透過盛宴合而為一，變得完整。"
L5_1.m_Talk_SCN = "不完整的知识、不完整的存在将通过盛宴成为一体，变得完整。"
L5_1.m_Talk_DEU = "The feast will complete the imperfect knowledge and perfect the imperfect beings."
L5_1.m_Talk_FRA = "The feast will complete the imperfect knowledge and perfect the imperfect beings."
