L7_1 = {}
L7_1.m_CutScenKey_Talk = "PRYDWEN_ACT2_INTERUDE5@7#Talk"
L7_1.m_CutScenProcessKey = 7
L7_1.m_CutScenID = 6000209
L7_1.m_CutScenStrID = "PRYDWEN_ACT2_INTERUDE5"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_Talk_KOREA = "모두 지식의 성찬을 준비하라.\n모두 연회를 시작하라."
L7_1.m_fTalkTime = 0.03
L7_1.m_bTalkCenterFadeIn = true
L7_1.m_Talk_JPN = "みんな、知識の聖餐を準備しろ。\nみんな、宴会を始めろ。"
L7_1.m_Talk_ENG = [[
Prepare the feast of knowledge.
Start the banquet.]]
L7_1.m_Talk_TWN = "大家準備知識的盛宴吧，\n大家開始宴會吧。"
L7_1.m_Talk_SCN = "大家准备知识的盛宴吧，\n大家开始宴会吧。"
L7_1.m_Talk_DEU = [[
Prepare the feast of knowledge.
Start the banquet.]]
L7_1.m_Talk_FRA = [[
Prepare the feast of knowledge.
Start the banquet.]]
L8_1 = {}
L8_1.m_CutScenKey_Talk = "PRYDWEN_ACT2_INTERUDE5@8#Talk"
L8_1.m_CutScenProcessKey = 8
L8_1.m_CutScenID = 6000209
L8_1.m_CutScenStrID = "PRYDWEN_ACT2_INTERUDE5"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_Talk_KOREA = "오랜 갈구와 허기의 끝이 마침내 도래했다."
L8_1.m_fTalkTime = 0.03
L8_1.m_bTalkCenterFadeIn = true
L8_1.m_Talk_JPN = "長い渇きと飢えの果てが、ついに訪れたのだ。"
L8_1.m_Talk_ENG = "The long thirst and hunger are finally coming to an end."
L8_1.m_Talk_TWN = "長久的渴望和饑餓終於到達了盡頭。"
L8_1.m_Talk_SCN = "长久的渴望和饥饿终于到达了尽头。"
L8_1.m_Talk_DEU = "The long thirst and hunger are finally coming to an end."
L8_1.m_Talk_FRA = "The long thirst and hunger are finally coming to an end."
L9_1 = {}
L9_1.m_CutScenKey_Talk = "PRYDWEN_ACT2_INTERUDE5@9#Talk"
L9_1.m_CutScenProcessKey = 9
L9_1.m_CutScenID = 6000209
L9_1.m_CutScenStrID = "PRYDWEN_ACT2_INTERUDE5"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_Talk_KOREA = "오늘의 성찬은 어린 양의 피와 살일지니.\n삼키는 자가 삼켜지고, 삼켜지는 자가 삼키리라."
L9_1.m_fTalkTime = 0.03
L9_1.m_bTalkCenterFadeIn = true
L9_1.m_Talk_JPN = "今日は子羊の血と肉が聖餐となり、\n飲み込む者が飲み込まれ、飲み込まれる者が飲み込むことになるだろう。"
L9_1.m_Talk_ENG = [[
Today, the blood and flesh of the young lamb will be on the table,
and the swallower shall become the swallowed.]]
L9_1.m_Talk_TWN = "今天的盛宴，是羔羊的血和肉。\n吞食者將被吞噬，被吞噬者將去吞食。"
L9_1.m_Talk_SCN = "今天的盛宴，是羔羊的血和肉。\n吞食者将被吞噬，被吞噬者将去吞食。"
L9_1.m_Talk_DEU = [[
Today, the blood and flesh of the young lamb will be on the table,
and the swallower shall become the swallowed.]]
L9_1.m_Talk_FRA = [[
Today, the blood and flesh of the young lamb will be on the table,
and the swallower shall become the swallowed.]]
