L12_1.m_fTalkTime = 0.03
L12_1.m_bTalkCenterFadeIn = true
L12_1.m_Talk_JPN = "聖餐の主が到着した。お母さんのお出ましだ。"
L12_1.m_Talk_ENG = "The host of the feast has arrived. Mother has arrived."
