L16_1.m_StartFXSoundName = "FX_CUTSCEN_NOISE_RUSTLE_02"
L16_1.m_CharStrID = "KNIGHT_PRYDWEN_ESPR_QM"
L16_1.m_Talk_KOREA = "내 이름과 명예를 걸고 너희에게 맹세하마."
L16_1.m_fTalkTime = 0.03
L16_1.m_Talk_JPN = "俺の名前と名誉をかけて、お前たちに誓おう。"
L16_1.m_Talk_ENG = "I swear on my name and honor."
L16_1.m_Talk_TWN = "我以我的名字和榮譽為賭注，向你們發誓。"
L16_1.m_Talk_SCN = "我以我的名字和荣誉为赌注，向你们发誓。"
L16_1.m_Talk_DEU = "I swear on my name and honor."
L16_1.m_Talk_FRA = "I swear on my name and honor."
L17_1 = {}
L17_1.m_CutScenKey_Talk = "PRYDWEN_ACT2_INTERUDE5@17#Talk"
L17_1.m_CutScenProcessKey = 17
L17_1.m_CutScenID = 6000209
L17_1.m_CutScenStrID = "PRYDWEN_ACT2_INTERUDE5"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_CharStrID = "KNIGHT_PRYDWEN_ESPR_QM"
L17_1.m_Talk_KOREA = "아무리 힘들어도, 아무리 오랜 시간이 걸려도 너희를 포기하지 않겠다."
L17_1.m_fTalkTime = 0.03
L17_1.m_Talk_JPN = "どんなに辛い思いをしても、どんなに長い時間がかかっても、俺はお前たちのことを諦めない。"
L17_1.m_Talk_ENG = "No matter how hard, no matter how long, I won't give up on you."
L17_1.m_Talk_TWN = "無論多累，會花費多少時間，我也不會放棄你們。"
L17_1.m_Talk_SCN = "无论多累，会花费多少时间，我也不会放弃你们。"
L17_1.m_Talk_DEU = "No matter how hard, no matter how long, I won't give up on you."
L17_1.m_Talk_FRA = "No matter how hard, no matter how long, I won't give up on you."
L18_1 = {}
