L40_1.m_Pos = "L"
L40_1.m_Talk_KOREA = "부탁이야, 앤. 이곳에서 도망치려면 다 같이 도망치자."
L40_1.m_fTalkTime = 0.03
L40_1.m_Talk_JPN = "お願い、アン。ここから逃げるなら、みんなで逃げよう。"
L40_1.m_Talk_ENG = "Please, Ann. If we're going to run away, let's run away all together!"
L40_1.m_Talk_TWN = "我求求你，安妮。想從這裡逃走，就帶著大家一起逃吧。"
L40_1.m_Talk_SCN = "我求求你，安妮。想从这里逃走，就带着大家一起逃吧。"
L40_1.m_Talk_DEU = "Please, Ann. If we're going to run away, let's run away all together!"
L40_1.m_Talk_FRA = "Please, Ann. If we're going to run away, let's run away all together!"
