L42_1.m_Pos = "R"
L42_1.m_Talk_KOREA = "전에 말했잖아. 보육원의 배후에는 정체 모를 세력이 있다고."
L42_1.m_fTalkTime = 0.03
L42_1.m_Talk_JPN = "前に言ったでしょ？　保育園の背後には、得体の知れない勢力があるって。"
L42_1.m_Talk_ENG = "I told you. There is an unknown force behind the orphanage."
