L42_1.m_Talk_SCN = "我之前跟你说过，孤儿院的背后有不明身份的势力。"
L42_1.m_Talk_DEU = "I told you. There is an unknown force behind the orphanage."
L42_1.m_Talk_FRA = "I told you. There is an unknown force behind the orphanage."
