L44_1.m_Pos = "C"
L44_1.m_Talk_KOREA = "우리 둘만 튀는 것도 붙잡힐 가능성이 큰데, 애들을 다 데려가겠다고?"
L44_1.m_fTalkTime = 0.03
L44_1.m_Talk_JPN = "私たちだけで逃げても捕まる可能性は高いのに、子どもたちをみんな連れて行くつもり？"
L44_1.m_Talk_ENG = "Our chances of getting caught are already high with just us two, but you want all the other kids with you too?"
