L12_1.m_Pos = "R"
L13_1 = "조만간 불을 지를 거니까, 애들한테 불이 나면 <color=#ffd34c>성황청</color>으로 대피하라고 알려주는 거야."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "もうすぐ火をつけるから、みんなに火事が起きたら<color=#ffd34c>聖皇庁</color>に待避してって教えてあげて。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Since we're setting fire soon, go tell the others to evacuate to the <color=#ffd34c>Holy Curia</color>."
L12_1.m_Talk_ENG = L13_1
L13_1 = "因為遲早會放火，所以你告訴孩子們，要是著火了就躲到<color=#ffd34c>聖皇廳</color>裡。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "因为迟早会放火，所以你告诉孩子们，要是着火了就躲到<color=#ffd34c>圣廷</color>里。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Since we're setting fire soon, go tell the others to evacuate to the <color=#ffd34c>Holy Curia</color>."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Since we're setting fire soon, go tell the others to evacuate to the <color=#ffd34c>Holy Curia</color>."
