L23_1 = "<color=#ff3636>오늘</color>의 주식은 주<color=#ff3636>인의 피</color>와 <b>살이</b>니, 삼<color=#ff3636>키는 자</color>가 삼켜지<color=#ff3636>게 되리라</color>."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "<color=#ff3636>今日</color>は主の<color=#ff3636>血と</color>肉が<b>主食と</b>なり、飲<color=#ff3636>み込む者</color>が飲み込ま<color=#ff3636>れることになるだろう</color>。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "<color=#ff3636>Today</color>, the blood and <b>flesh</b> of the ho<color=#ff3636>st</color> will be on the table, and the swa<color=#ff3636>llower</color> shall become the <color=#ff3636>swallow</color>ed."
L22_1.m_Talk_ENG = L23_1
