L17_1 = "하지만 아직 어렸던 우리가 무언가를 바꾸는 건 쉽지 않았고."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L16_1.m_bTalkCenterFadeIn = true
L17_1 = "だけど、幼い私たちに何かを変えることはそう簡単ではなかった。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "We were young, and it wasn't easy to change something."
L16_1.m_Talk_ENG = L17_1
L17_1 = "但是，年幼的我們想要改變什麼並不容易。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "但是，年幼的我们想要改变什么并不容易。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "We were young, and it wasn't easy to change something."
L16_1.m_Talk_DEU = L17_1
L17_1 = "We were young, and it wasn't easy to change something."
L16_1.m_Talk_FRA = L17_1
