L17_1.m_CutScenID = 6000209
L17_1.m_CutScenStrID = "PRYDWEN_ACT2_INTERUDE5"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L18_1 = "운명의 순간은 항상 그렇듯, 느닷없이 찾아왔다."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L17_1.m_bTalkCenterFadeIn = true
L18_1 = "運命の瞬間はいつも、いきなり訪れる。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "And fate, as always, makes an unexpected visit."
L17_1.m_Talk_ENG = L18_1
L18_1 = "命運的瞬間和往常一樣，來得非常突然。"
L17_1.m_Talk_TWN = L18_1
