L27_1 = "<color=#ff3636>오늘</color>의 주식은 주<color=#ff3636>인의 피</color>와 <b>살이</b>니, 삼<color=#ff3636>키는 자</color>가 삼켜지<color=#ff3636>게 되리라</color>."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "<color=#ff3636>今日</color>は主の<color=#ff3636>血と</color>肉が<b>主食と</b>なり、飲<color=#ff3636>み込む者</color>が飲み込ま<color=#ff3636>れることになるだろう</color>。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "<color=#ff3636>Today</color>, the blood and <b>flesh</b> of the ho<color=#ff3636>st</color> will be on the table, and the swa<color=#ff3636>llower</color> shall become the <color=#ff3636>swallow</color>ed."
L26_1.m_Talk_ENG = L27_1
L27_1 = "<color=#ff3636>今天</color>的主食是主<color=#ff3636>人的血</color>和<b>肉</b>。所以，吞<color=#ff3636>食者</color>就去吞<color=#ff3636>食吧</color>。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "<color=#ff3636>今天</color>的主食是主<color=#ff3636>人的血</color>和<b>肉</b>。所以，吞<color=#ff3636>食者</color>就去吞<color=#ff3636>食吧</color>。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "<color=#ff3636>Today</color>, the blood and <b>flesh</b> of the ho<color=#ff3636>st</color> will be on the table, and the swa<color=#ff3636>llower</color> shall become the <color=#ff3636>swallow</color>ed."
L26_1.m_Talk_DEU = L27_1
L27_1 = "<color=#ff3636>Today</color>, the blood and <b>flesh</b> of the ho<color=#ff3636>st</color> will be on the table, and the swa<color=#ff3636>llower</color> shall become the <color=#ff3636>swallow</color>ed."
